			bits.OnesCount64(a[12]) + bits.OnesCount64(a[13]) +
			bits.OnesCount64(a[14]) + bits.OnesCount64(a[15])
		xs = xs[16:]
	}
	if len(xs) >= 8 {
		n += bits.OnesCount64(xs[0]) + bits.OnesCount64(xs[1]) +
			bits.OnesCount64(xs[2]) + bits.OnesCount64(xs[3]) +
